INSERT INTO `v1_ec9a5cee5b2d79422c14537557cebe750643eeb1cd28a484957644dacc16de8d` VALUES (3.414, 1, 190801, -416.5, "ミッションをクリアすると、\n報酬がもらえますよ！\n頑張ってください", 1000001, "2025/01/31 12:00:00", 1, 2, 0, "2030/01/01 14:59:59", 1, 62, "カリン");
INSERT INTO `v1_ec9a5cee5b2d79422c14537557cebe750643eeb1cd28a484957644dacc16de8d` VALUES (3.099, 2, 190801, -416.5, "ミッションをクリアして、\n報酬をゲットしましょう！", 1000002, "2025/01/31 12:00:00", 1, 2, 0, "2030/01/01 14:59:59", 1, 62, "カリン");
INSERT INTO `v1_ec9a5cee5b2d79422c14537557cebe750643eeb1cd28a484957644dacc16de8d` VALUES (2.801, 3, 190801, -416.5, "受け取ることができる\n報酬があるようです\n確認してみてください", 1000003, "2025/01/31 12:00:00", 1, 2, 0, "2030/01/01 14:59:59", 1, 63, "カリン");
INSERT INTO `v1_ec9a5cee5b2d79422c14537557cebe750643eeb1cd28a484957644dacc16de8d` VALUES (0, 4, 190801, -416.5, "報酬がもらえますよ！\nチェックしてみてください", 1000004, "2025/01/31 12:00:00", 1, 2, 0, "2030/01/01 14:59:59", 2, 63, "カリン");
INSERT INTO `v1_ec9a5cee5b2d79422c14537557cebe750643eeb1cd28a484957644dacc16de8d` VALUES (2.12, 5, 190801, -363, "ギルド管理協会です！\nイベント報酬券をお持ちでしたら、様々なアイテムと交換できますよ", 1000005, "2025/01/31 12:00:00", 1, 1, 0, "2030/01/01 14:59:59", 2, 64, "カリン");
INSERT INTO `v1_ec9a5cee5b2d79422c14537557cebe750643eeb1cd28a484957644dacc16de8d` VALUES (1.68, 6, 190801, -363, "お疲れさまです！\nこちらでイベント報酬券とアイテムを交換することができますよ", 1000006, "2025/01/31 12:00:00", 1, 2, 0, "2030/01/01 14:59:59", 1, 64, "カリン");
INSERT INTO `v1_ec9a5cee5b2d79422c14537557cebe750643eeb1cd28a484957644dacc16de8d` VALUES (2.33, 7, 190801, -363, "いつもありがとうございます！\n報酬交換ですか？\nでは、イベント報酬券とお引き換えいたしますね", 1000007, "2025/01/31 12:00:00", 1, 1, 0, "2030/01/01 14:59:59", 2, 64, "カリン");
INSERT INTO `v1_ec9a5cee5b2d79422c14537557cebe750643eeb1cd28a484957644dacc16de8d` VALUES (5.18, 101, 133701, -285, "今度の敵は、アタシにとっても\n放ってはおけない存在だ\n少年、アタシも全力で行くからさ\n一緒に守ろう、この世界を", 1020101, "2025/01/31 12:00:00", 10201, 7, -6, "2030/01/01 14:59:59", 3, 61, "ラビリスタ");
INSERT INTO `v1_ec9a5cee5b2d79422c14537557cebe750643eeb1cd28a484957644dacc16de8d` VALUES (8.77, 201, 133901, -285, "退屈の吹き飛ぶような\n戦いの気配がするなぁ坊や\nさっさとワタシをそこへ連れてゆけ\n世界も守ってやるさ、ついでにな", 1020102, "2025/01/31 12:00:00", 10201, 2, -2, "2030/01/01 14:59:59", 1, 61, "クリスティーナ");
INSERT INTO `v1_ec9a5cee5b2d79422c14537557cebe750643eeb1cd28a484957644dacc16de8d` VALUES (15.5, 301, 133801, -285, "おや、私の力が必要……と？\nグレゴールが手伝うそうですよ\n私は戦わないのか、という顔ですね\n……考えておきます", 1020103, "2025/01/31 12:00:00", 10201, 1, 0, "2030/01/01 14:59:59", 6, 61, "ネネカ");
INSERT INTO `v1_ec9a5cee5b2d79422c14537557cebe750643eeb1cd28a484957644dacc16de8d` VALUES (9.061, 101, 134301, -285, "わたしだけの歌…\n一緒に、探してくれる…？\nあなたがいれば…\nもっとがんばれるから…", 1020201, "2025/02/28 12:00:00", 10202, 5, 0, "2030/01/01 14:59:59", 2, 61, "ランファ");
INSERT INTO `v1_ec9a5cee5b2d79422c14537557cebe750643eeb1cd28a484957644dacc16de8d` VALUES (7.699, 201, 134401, -285, "同じ唱喚士として、仲間として\n私にできることをします\n…これも、あなたが\n背中を押してくれたおかげですよ", 1020202, "2025/02/28 12:00:00", 10202, 2, 0, "2030/01/01 14:59:59", 1, 61, "チカ");
INSERT INTO `v1_ec9a5cee5b2d79422c14537557cebe750643eeb1cd28a484957644dacc16de8d` VALUES (8.595, 101, 134601, -285, "世界の平和が私とクローチェさんに\nかかってるんですよね？\nぼっちには過大すぎる期待ですけど\nふ、二人でなら背負ってみせます！", 1020301, "2025/03/31 12:00:00", 10203, 2, 0, "2030/01/01 14:59:59", 1, 61, "アオイ");
INSERT INTO `v1_ec9a5cee5b2d79422c14537557cebe750643eeb1cd28a484957644dacc16de8d` VALUES (7.758, 201, 134501, -285, "新しく手に入れたこの翼で…\nナイトさんがどこにいたって\nわたし、駆けつけちゃいますよっ！\nクローチェ・エアリアル発進ですっ", 1020302, "2025/03/31 12:00:00", 10203, 2, 0, "2030/01/01 14:59:59", 1, 61, "クローチェ");
INSERT INTO `v1_ec9a5cee5b2d79422c14537557cebe750643eeb1cd28a484957644dacc16de8d` VALUES (7, 101, 132302, -285, "今日はダーリンとの初デート♪\n二人でショッピングして、その後は\n…って私、指名手配されてる！？\nちょ、た…助けてダーリン～！！", 1020401, "2025/04/30 12:00:00", 10204, 6, 0, "2030/01/01 14:59:59", 2, 61, "ルイズマリー");
INSERT INTO `v1_ec9a5cee5b2d79422c14537557cebe750643eeb1cd28a484957644dacc16de8d` VALUES (7.904, 201, 132402, -285, "ルイちゃんのおばあちゃん優しくて\nいつもにこにこで、イロハ大好き♪\nでも一番好きなのは、角がすっごく\n大きくてかっこいいとこなんだ～♪", 1020402, "2025/04/30 12:00:00", 10204, 2, 0, "2030/01/01 14:59:59", 1, 61, "イロハ");
INSERT INTO `v1_ec9a5cee5b2d79422c14537557cebe750643eeb1cd28a484957644dacc16de8d` VALUES (8.487, 301, 132502, -285, "ノゾミちゃんのおかげで売上が安定\nしてきたのに、臨時休業、痛すぎる\n…ま、ルイちゃんのために\n一肌脱ぐか。行くよイロハ～", 1020403, "2025/04/30 12:00:00", 10204, 2, 0, "2030/01/01 14:59:59", 4, 61, "ソノ");
INSERT INTO `v1_ec9a5cee5b2d79422c14537557cebe750643eeb1cd28a484957644dacc16de8d` VALUES (8.763, 101, 134901, -285, "ヲ～ッホッホ♪\nあたくし様と同じお空気を吸える\nお幸運を噛みしめなさいですわ～♪\nヲ～ッホッホッホ～♪", 1020502, "2025/05/31 12:00:00", 10205, 2, 0, "2030/01/01 14:59:59", 1, 61, "カノン");
INSERT INTO `v1_ec9a5cee5b2d79422c14537557cebe750643eeb1cd28a484957644dacc16de8d` VALUES (6.417, 201, 134801, -285, "いきますよ騎士さん！\nカノンさんと力を合わせて…力を…\n…本当にあの人なんなんです？\nこれまでになく不安なんですけど！", 1020503, "2025/05/31 12:00:00", 10205, 3, 0, "2030/01/01 14:59:59", 1, 61, "ツムギ");
INSERT INTO `v1_ec9a5cee5b2d79422c14537557cebe750643eeb1cd28a484957644dacc16de8d` VALUES (10.335, 101, 135001, -285, "『願いが叶う海岸』か…怪しい\nだというのに、阿賀斗紫布菜たちは\n呑気に戯れている…見ていられない\n騎士クンは、わたしが守ってみせる", 1020601, "2025/06/30 12:00:00", 10206, 7, 0, "2030/01/01 14:59:59", 3, 61, "エリス");
INSERT INTO `v1_ec9a5cee5b2d79422c14537557cebe750643eeb1cd28a484957644dacc16de8d` VALUES (6.281, 201, 135101, -285, "せっかくの夏休みなんだし\nたまにはビーチでゆっくりしましょ\n…え、もしかしてこの夏もあんまり\n休めなかったりする感じなの？", 1020602, "2025/06/30 12:00:00", 10206, 4, 0, "2030/01/01 14:59:59", 2, 61, "シェフィ");
INSERT INTO `v1_ec9a5cee5b2d79422c14537557cebe750643eeb1cd28a484957644dacc16de8d` VALUES (12.244, 301, 135201, -285, "いっぱい。たべて\nおおきく。なると\nせーぎ。まもれる。はず\nお兄。いっしょに。スイカ。たべよ", 1020603, "2025/06/30 12:00:00", 10206, 2, 0, "2030/01/01 14:59:59", 1, 61, "プレシア");
INSERT INTO `v1_ec9a5cee5b2d79422c14537557cebe750643eeb1cd28a484957644dacc16de8d` VALUES (6.339, 101, 135301, -285, "ひと夏の冒険のはじまりです！\nアネモネさんも楽しんでくれたら\n…できれば、もう少し\n仲良くなれたらうれしいな…", 1020701, "2025/07/31 12:00:00", 10207, 8, 0, "2030/01/01 14:59:59", 2, 61, "クリア");
INSERT INTO `v1_ec9a5cee5b2d79422c14537557cebe750643eeb1cd28a484957644dacc16de8d` VALUES (8.184, 201, 135401, -285, "─幻の花…\n本当にあるのか謎─ですけど\n探すくらいは、\n付き合ってもいいです", 1020702, "2025/07/31 12:00:00", 10207, 9, 0, "2030/01/01 14:59:59", 7, 61, "アネモネ");
INSERT INTO `v1_ec9a5cee5b2d79422c14537557cebe750643eeb1cd28a484957644dacc16de8d` VALUES (3.906, 101, 129101, -285, "あははっ！　笑う門には福来る！\n笑ってればきっと、複製世界にも\n未来はやってくるって信じてる！\nそうだよね、シナツちゃん！", 1020801, "2025/08/31 12:00:00", 10208, 2, 0, "2030/01/01 14:59:59", 9, 61, "アイラ");
INSERT INTO `v1_ec9a5cee5b2d79422c14537557cebe750643eeb1cd28a484957644dacc16de8d` VALUES (14.465, 201, 129201, -285, "繰り返されるリセットの先の未来\n何度願っても手に入らなかった未来\n…でも、私は諦めない。絶対にだ\nキミも同じだろ…アイラ？", 1020802, "2025/08/31 12:00:00", 10208, 2, 0, "2030/01/01 14:59:59", 1, 61, "シナツ");
INSERT INTO `v1_ec9a5cee5b2d79422c14537557cebe750643eeb1cd28a484957644dacc16de8d` VALUES (8.662, 301, 100101, -285, "アイラの世界のみんなも、\n一生懸命生きてるんだ…！\n…なのに、世界の危機だなんて！\nあたし、絶対、絶対力になるよ！", 1020803, "2025/08/31 12:00:00", 10208, 3, 0, "2030/01/01 14:59:59", 4, 61, "ヒヨリ");
INSERT INTO `v1_ec9a5cee5b2d79422c14537557cebe750643eeb1cd28a484957644dacc16de8d` VALUES (10.915, 401, 100301, -285, "シナツ…もう一人の私\n彼女が大切にしている世界を\n絶対に終わらせはしない…！\n彼女と笑い合える未来のために！", 1020804, "2025/08/31 12:00:00", 10208, 3, 0, "2030/01/01 14:59:59", 1, 61, "レイ");
INSERT INTO `v1_ec9a5cee5b2d79422c14537557cebe750643eeb1cd28a484957644dacc16de8d` VALUES (6.042, 101, 135802, -285, "あ、ど、ども…\nあ、あんま見ねぇでくれっと\nその、恥ずかしくて…\n体が熱くなって、溶けちまう…", 1020901, "2025/09/30 12:00:00", 10209, 7, 0, "2030/01/01 14:59:59", 1, 61, "ユキノ");
INSERT INTO `v1_ec9a5cee5b2d79422c14537557cebe750643eeb1cd28a484957644dacc16de8d` VALUES (9.402, 201, 135903, -285, "なんで俺が幽霊に…意味不明だ\nこれじゃ死んでも死にきれねェ\n悪ィがこれも何かの縁だ、\nよろしく頼むぜ騎士公", 1020902, "2025/09/30 12:00:00", 10209, 1, 0, "2030/01/01 14:59:59", 4, 61, "サツキ");
INSERT INTO `v1_ec9a5cee5b2d79422c14537557cebe750643eeb1cd28a484957644dacc16de8d` VALUES (8.16, 301, 136902, -285, "う、うじゅる…\nサツキ姉しゃまを助けるためにも\nまずは、腹ごしらえでしゅね…！\nタコ焼き、召し上がってくだしゃい", 1020903, "2025/09/30 12:00:00", 10209, 1, 0, "2030/01/01 14:59:59", 8, 61, "ルルィ");
INSERT INTO `v1_ec9a5cee5b2d79422c14537557cebe750643eeb1cd28a484957644dacc16de8d` VALUES (5, 101, 137401, -285, "ひさしぶりのジオ・ゲヘナ\n歓迎パーティーで起きた殺人事件！\nランドソルの名探偵の名にかけて\n解き明かしてみせようじゃないか！", 1021001, "2025/10/31 12:00:00", 10210, 2, 0, "2030/01/01 14:59:59", 3, 61, "カスミ");
INSERT INTO `v1_ec9a5cee5b2d79422c14537557cebe750643eeb1cd28a484957644dacc16de8d` VALUES (8.12, 201, 136001, -285, "…わたしはどこの誰なのでしょう\nどこから来てどこへ行くのでしょう\nこの事件の真相が分かれば、\n何かが掴めるような気がいたします", 1021002, "2025/10/31 12:00:00", 10210, 1, 0, "2030/01/01 14:59:59", 4, 61, "アラクネ");
INSERT INTO `v1_ec9a5cee5b2d79422c14537557cebe750643eeb1cd28a484957644dacc16de8d` VALUES (6.386, 301, 136202, -285, "ナーナ、すいりとかろんぱとか、\nむずかしくてわかんないけど…\nお友だちとドーナツのためならっ\nせーいっぱいがんばるよっ！", 1021003, "2025/10/31 12:00:00", 10210, 2, 0, "2030/01/01 14:59:59", 4, 61, "ナーナ");
INSERT INTO `v1_ec9a5cee5b2d79422c14537557cebe750643eeb1cd28a484957644dacc16de8d` VALUES (7.438, 101, 136402, -285, "騎士クンに想いを伝えたい…だから\nミソラちゃん、わたしがんばるね！\n…あれ？　わたし、なんでこんなに\n必死になってるんだろう…？", 1021101, "2025/11/30 12:00:00", 10211, 4, 0, "2030/01/01 14:59:59", 3, 61, "ユイ");
INSERT INTO `v1_ec9a5cee5b2d79422c14537557cebe750643eeb1cd28a484957644dacc16de8d` VALUES (8.35, 201, 136302, -285, "騎士さんとのデートはわたしに\nお任せです★　なのでユイさんは\n安心して計画に専念して…たくさん\nドキドキしちゃってくださいね", 1021102, "2025/11/30 12:00:00", 10211, 5, 0, "2030/01/01 14:59:59", 1, 61, "ミソラ");
INSERT INTO `v1_ec9a5cee5b2d79422c14537557cebe750643eeb1cd28a484957644dacc16de8d` VALUES (5, 101, 136501, -285, "新しい年がやってくるね！\nお正月の料理も飾りつけも、\nお姉ちゃんにお任せだよ♪\nみんなで楽しく新年を迎えよう！", 1021201, "2025/12/31 12:00:00", 10212, 2, 0, "2030/01/01 14:59:59", 1, 61, "シズル");
INSERT INTO `v1_ec9a5cee5b2d79422c14537557cebe750643eeb1cd28a484957644dacc16de8d` VALUES (5.25, 201, 137902, -285, "おうちの掃除もトラブルも、 \n世界を揺るがす大ピンチも！\n今年のことは今年のうちに \nサッサと片付けちゃいますっ！", 1021202, "2025/12/31 12:00:00", 10212, 2, 0, "2030/01/01 14:59:59", 1, 61, "リノ");
INSERT INTO `v1_ec9a5cee5b2d79422c14537557cebe750643eeb1cd28a484957644dacc16de8d` VALUES (7.5, 301, 106801, -285, "年の瀬はギルドマスターも\nつい駆け回っちゃう忙しい時期だ！\n一年いろいろあったけど\nお互いイイ年を迎えよう、少年！", 1021203, "2025/12/31 12:00:00", 10212, 2, 0, "2030/01/01 14:59:59", 1, 61, "ラビリスタ");
INSERT INTO `v1_ec9a5cee5b2d79422c14537557cebe750643eeb1cd28a484957644dacc16de8d` VALUES (8.204, 101, 126501, -285, "漂う異国の料理の香り…それだけで\n世界中を旅した気分に浸れますね\nふふ、ほらクローチェ\nあまりはしゃぎすぎないように…♪", 1021301, "2026/01/31 12:00:00", 10213, 2, 0, "2030/01/01 14:59:59", 1, 61, "ライラエル");
INSERT INTO `v1_ec9a5cee5b2d79422c14537557cebe750643eeb1cd28a484957644dacc16de8d` VALUES (7.176, 201, 129701, -285, "異界の姫君と煮炊きにて競い合う…\n感奮興起、いとをかし\n華やかなる祭典と相成るよう、一肌\n脱がせていただきとう存じまする", 1021302, "2026/01/31 12:00:00", 10213, 2, 0, "2030/01/01 14:59:59", 1, 61, "ネフィ＝ネラ");
INSERT INTO `v1_ec9a5cee5b2d79422c14537557cebe750643eeb1cd28a484957644dacc16de8d` VALUES (8.602, 301, 133101, -285, "『ビストロプリンセス』のために\n料理の特訓を重ねてまいりました\nこの料理で騎士様の…い、いえ\n皆様の心とお腹を満たしますわ！", 1021303, "2026/01/31 12:00:00", 10213, 5, 0, "2030/01/01 14:59:59", 1, 61, "ヴァイオレット");
INSERT INTO `v1_ec9a5cee5b2d79422c14537557cebe750643eeb1cd28a484957644dacc16de8d` VALUES (10.14, 102, 138101, -285, "多様な味わいが織りなすハーモニー\nそれこそが我が国の矜持です\nもしもそれを乱すようであれば\nわたしも優しくはありませんよ？", 1021304, "2026/02/06 12:00:00", 10213, 3, 0, "2030/01/01 14:59:59", 1, 61, "ライラエル");
INSERT INTO `v1_ec9a5cee5b2d79422c14537557cebe750643eeb1cd28a484957644dacc16de8d` VALUES (10.152, 202, 138201, -285, "煉獄の穢土にてひと際輝く民草の心\n此れを守護りまするがわっちの責務\n如何な困難待ち受けようと\n不退転の矜持に揺らぎはありんせん", 1021305, "2026/02/06 12:00:00", 10213, 7, 0, "2030/01/01 14:59:59", 1, 61, "ネフィ＝ネラ");
INSERT INTO `v1_ec9a5cee5b2d79422c14537557cebe750643eeb1cd28a484957644dacc16de8d` VALUES (9.688, 302, 138001, -285, "裏世界の皆様は危機を脱し、\n残るはランドソルの皆様のみ…\n彼らを救い出すために、どうか…\nお立ち下さいペコリーヌ姫…！", 1021306, "2026/02/06 12:00:00", 10213, 3, 0, "2030/01/01 14:59:59", 4, 61, "ヴァイオレット");
INSERT INTO `v1_ec9a5cee5b2d79422c14537557cebe750643eeb1cd28a484957644dacc16de8d` VALUES (5.928, 401, 138301, -285, "みなさん、お待たせしちゃいました\nペコリーヌ、完全復活です☆\nみなさんの食卓を守るため\nもう二度と、わたしはめげません！", 1021307, "2026/02/12 12:00:00", 10213, 1, 0, "2030/01/01 14:59:59", 2, 61, "ペコリーヌ");
INSERT INTO `v1_ec9a5cee5b2d79422c14537557cebe750643eeb1cd28a484957644dacc16de8d` VALUES (9.19, 101, 138702, -285, "成行きで参加することになっちゃっ\nた尻相撲大会。ううっ、恥ずかしい\nけどやるしかないよね。…騎士さん\nいっぱい応援してくださいね？", 1021401, "2026/02/28 12:00:00", 10214, 2, 0, "2030/01/01 14:59:59", 4, 61, "ワカナ");
INSERT INTO `v1_ec9a5cee5b2d79422c14537557cebe750643eeb1cd28a484957644dacc16de8d` VALUES (8.724, 201, 138802, -285, "「お姉ちゃんを守れる自分になる」\nあの日の約束、今こそ果たしてみせ\nます。例えお姉ちゃんに背くことに\nなっても。例えそれが尻相撲でも！", 1021402, "2026/02/28 12:00:00", 10214, 3, 0, "2030/01/01 14:59:59", 1, 61, "シオリ");
INSERT INTO `v1_ec9a5cee5b2d79422c14537557cebe750643eeb1cd28a484957644dacc16de8d` VALUES (7.758, 101, 138902, -285, "私がへんたいふしんしゃさんって…\nただ生きているだけなのに、ひどい\n…まぁ死んでるんですけど…とか\n言ってる暇もない感じですか？", 1021501, "2026/03/31 12:00:00", 10215, 1, 0, "2030/01/01 14:59:59", 4, 61, "グレイス");
INSERT INTO `v1_ec9a5cee5b2d79422c14537557cebe750643eeb1cd28a484957644dacc16de8d` VALUES (6.375, 201, 139002, -285, "あの、助けてください！\n私がへんたいふしんしゃさんに\nなっちゃったみたいなんです…！\nどういう意味かは私もわかりません", 1021502, "2026/03/31 12:00:00", 10215, 4, 0, "2030/01/01 14:59:59", 6, 61, "キョウカ");
INSERT INTO `v1_ec9a5cee5b2d79422c14537557cebe750643eeb1cd28a484957644dacc16de8d` VALUES (6.173, 301, 136902, -285, "ましゃか、グレイス姉しゃまたちが\nへんたいふしんしゃさんだなんて…\n騎士しゃん。あたちたちも協力ちて\n二人の破滅エンドを回避ちましょう", 1021503, "2026/03/31 12:00:00", 10215, 1, 0, "2030/01/01 14:59:59", 6, 61, "ルルィ");
INSERT INTO `v1_ec9a5cee5b2d79422c14537557cebe750643eeb1cd28a484957644dacc16de8d` VALUES (4.202, 101, 139202, -285, "違う世界に来ちゃうし、\n驚きの連続だけど…\nわたしも精いっぱい頑張ります！\nアストルムのみんなと一緒に！", 1021601, "2026/04/30 12:00:00", 10216, 2, 0, "2030/01/01 14:59:59", 6, 61, "ミホ");
INSERT INTO `v1_ec9a5cee5b2d79422c14537557cebe750643eeb1cd28a484957644dacc16de8d` VALUES (2.842, 201, 139302, -285, "想定外の事象が発生したな…だが\nいかなる苦境も切り抜けてみせる\nいつもの自分とは違う姿になっても\nわたしはわたし、西住流だ", 1021602, "2026/04/30 12:00:00", 10216, 1, 0, "2030/01/01 14:59:59", 6, 61, "マホ");
INSERT INTO `v1_ec9a5cee5b2d79422c14537557cebe750643eeb1cd28a484957644dacc16de8d` VALUES (4.598, 301, 139402, -285, "何でこんなことになっているのか\n全然わからないけど、迷ってる暇は\nないわ。黒森峰の次期隊長として、\n前進あるのみ！　これも戦車道よ！", 1021603, "2026/04/30 12:00:00", 10216, 1, 0, "2030/01/01 14:59:59", 4, 61, "エリカ");
INSERT INTO `v1_ec9a5cee5b2d79422c14537557cebe750643eeb1cd28a484957644dacc16de8d` VALUES (6.533, 101, 125802, -285, "わたくしたちの悲願は、ロストさせ\nてしまった方々をお助けすること…\nそのためなら、どのような辛苦にも\n耐え抜いてみせます…！", 1021701, "2026/05/31 12:00:00", 10217, 3, 0, "2030/01/01 14:59:59", 4, 61, "リリ");
INSERT INTO `v1_ec9a5cee5b2d79422c14537557cebe750643eeb1cd28a484957644dacc16de8d` VALUES (5, 301, 126102, -285, "みんなも。せーぎも。\nクリアも。パパ、も。\nぜったい、たすける。\nみててね。お兄。", 1021702, "2026/05/31 12:00:00", 10217, 3, 0, "2030/01/01 14:59:59", 3, 61, "プレシア");
INSERT INTO `v1_ec9a5cee5b2d79422c14537557cebe750643eeb1cd28a484957644dacc16de8d` VALUES (5.214, 201, 126002, -285, "癒しの力を使うこと…\nもう、ためらいません！\nモネちゃんやお兄さん…\nみんなに許してもらうためにも！", 1021703, "2026/05/31 12:00:00", 10217, 4, 0, "2030/01/01 14:59:59", 3, 61, "クリア");
INSERT INTO `v1_ec9a5cee5b2d79422c14537557cebe750643eeb1cd28a484957644dacc16de8d` VALUES (8.781, 102, 139501, -285, "ヴァルキュリア─皆様を助けたい\nという願いを、力にできるのなら…\nわたくしたちは、きっと誰にも\n負けません！　一意専心です…！", 1021704, "2026/05/31 12:00:00", 10217, 3, 0, "2030/01/01 14:59:59", 1, 61, "リリ");
INSERT INTO `v1_ec9a5cee5b2d79422c14537557cebe750643eeb1cd28a484957644dacc16de8d` VALUES (6.529, 202, 139601, -285, "このヴァルキュリアって職業、\nまるで天使みたいな格好ですよね\nうーん…『聖女』ちゃんって\n呼ばれるよりは、マシかな？", 1021705, "2026/05/31 12:00:00", 10217, 1, 0, "2030/01/01 14:59:59", 2, 61, "クリア");
INSERT INTO `v1_ec9a5cee5b2d79422c14537557cebe750643eeb1cd28a484957644dacc16de8d` VALUES (3.195, 302, 139701, -285, "ばるきり。もーど。\nはね。まっしろ。\nはっぴーちゃんと。おなじ。\nいいかんじ。", 1021706, "2026/05/31 12:00:00", 10217, 2, 0, "2030/01/01 14:59:59", 3, 61, "プレシア");
INSERT INTO `v1_ec9a5cee5b2d79422c14537557cebe750643eeb1cd28a484957644dacc16de8d` VALUES (12.43, 101, 139902, -285, "ダーリンと一緒に南の島で\nリゾート開発なんて夢みたい♪\nああ…幸せ、最高の夏だわ…\n触れたら爆発さえしなければ～…っ", 1021801, "2026/06/30 12:00:00", 10218, 3, 0, "2030/01/01 14:59:59", 2, 61, "ルイズマリー");
INSERT INTO `v1_ec9a5cee5b2d79422c14537557cebe750643eeb1cd28a484957644dacc16de8d` VALUES (6.35, 201, 140001, -285, "青い空、白い雲…無人島リゾートで\n大儲けですわ～♪　こらこらそこ、\nイチャついてるんじゃないですのよ\n触れたらドカンですわよ、ドカン！", 1021802, "2026/06/30 12:00:00", 10218, 3, 0, "2030/01/01 14:59:59", 2, 61, "クレジッタ");
INSERT INTO `v1_ec9a5cee5b2d79422c14537557cebe750643eeb1cd28a484957644dacc16de8d` VALUES (10.23, 101, 140102, -285, "みんなはかわいいぼくを見られて、\nぼくはみんなからラヴをもらう♡\n最高のウィンウィンだよね、これ♡\nで、最後はお兄さんをドレーに…♡", 1021901, "2026/07/31 12:00:00", 10219, 5, 0, "2030/01/01 14:59:59", 1, 61, "フブキ");
INSERT INTO `v1_ec9a5cee5b2d79422c14537557cebe750643eeb1cd28a484957644dacc16de8d` VALUES (5.584, 201, 140201, -285, "けんぞくとたくさん遊ぶためにも、\nみんなからラヴをもらわなくちゃ♪\nバズっちゃおー作戦、\n一緒に考えてね！　けんぞくぅ♪", 1021902, "2026/07/31 12:00:00", 10219, 2, 0, "2030/01/01 14:59:59", 1, 61, "ヴァンピィ");
INSERT INTO `v1_ec9a5cee5b2d79422c14537557cebe750643eeb1cd28a484957644dacc16de8d` VALUES (2.8, 201, 126401, -285, "あっちもこっちも、\nエマージェンシーですっ！\nみんなのピンチを助けるために\n行きましょうっ、ナイトさんっ！", 1022001, "2026/08/31 12:00:00", 10220, 3, 0, "2030/01/01 14:59:59", 6, 61, "クローチェ");
INSERT INTO `v1_ec9a5cee5b2d79422c14537557cebe750643eeb1cd28a484957644dacc16de8d` VALUES (8.9, 101, 127802, -285, "みんながあたしを許してくれても…\nあたしは、あたしを許せない\nそれでも…この世界が危ないなら\n迷ってなんか、いられない", 1022002, "2026/08/31 12:00:00", 10220, 3, 0, "2030/01/01 14:59:59", 4, 61, "ヴルム");
INSERT INTO `v1_ec9a5cee5b2d79422c14537557cebe750643eeb1cd28a484957644dacc16de8d` VALUES (4.49, 202, 140602, -285, "クローチェ、サブマリンモードっ\n換装完了ですっ♪\nどんな荒波も、ナイトさんとなら\n越えちゃいますからっ！", 1022003, "2026/08/31 12:00:00", 10220, 1, 0, "2030/01/01 14:59:59", 2, 61, "クローチェ");
INSERT INTO `v1_ec9a5cee5b2d79422c14537557cebe750643eeb1cd28a484957644dacc16de8d` VALUES (9.42, 102, 140501, -285, "偽物でも、創り物でもいい\nあたしの中にある気持ちは、\nあたしの本物だから\n今度こそ、この力で守ってみせる", 1022004, "2026/08/31 12:00:00", 10220, 3, 0, "2030/01/01 14:59:59", 1, 61, "ヴルム");
INSERT INTO `v1_ec9a5cee5b2d79422c14537557cebe750643eeb1cd28a484957644dacc16de8d` VALUES (7, 301, 140402, -285, "世界と向き合うなんてこと…\n私には、わからない\nそれでも、受けた借りは\nちゃんと返さないとね", 1022005, "2026/08/31 12:00:00", 10220, 1, 0, "2030/01/01 14:59:59", 4, 61, "リーザ");
INSERT INTO `v1_ec9a5cee5b2d79422c14537557cebe750643eeb1cd28a484957644dacc16de8d` VALUES (8.61, 101, 141101, -285, "ゲームの世界、ね\n分からないことばかりだけれど\nやることは変わらないわ\nどんな場所でもわたしは負けない！", 1022101, "2026/10/31 12:00:00", 10221, 3, 0, "2030/01/01 14:59:59", 1, 61, "アーモンドアイ");
INSERT INTO `v1_ec9a5cee5b2d79422c14537557cebe750643eeb1cd28a484957644dacc16de8d` VALUES (3.55, 201, 141201, -285, "ゴルシさんは相変わらずやねぇ…\nまぁせっかくの異世界やし\nいつもと違うレース、\n楽しませてもらいましょ", 1022102, "2026/10/31 12:00:00", 10221, 1, 0, "2030/01/01 14:59:59", 6, 61, "ラッキーライラック");
INSERT INTO `v1_ec9a5cee5b2d79422c14537557cebe750643eeb1cd28a484957644dacc16de8d` VALUES (8.26, 301, 141301, -285, "なんて美しい世界でしょう…！\n現実では見られない景色ばかり\nぜひ一度、この世界の大自然を\n隅から隅まで駆け抜けてみたいです", 1022103, "2026/10/31 12:00:00", 10221, 1, 0, "2030/01/01 14:59:59", 2, 61, "デアリングタクト");
INSERT INTO `v1_ec9a5cee5b2d79422c14537557cebe750643eeb1cd28a484957644dacc16de8d` VALUES (8.79, 401, 141001, -285, "来ったぞ～来ったぞ～\nアストルム～っと！\nな～んか平和そうな世界だな\nちょっくら盛り上げてくっか！", 1022104, "2026/10/31 12:00:00", 10221, 1, 0, "2030/01/01 14:59:59", 2, 61, "ゴールドシップ");
INSERT INTO `v1_ec9a5cee5b2d79422c14537557cebe750643eeb1cd28a484957644dacc16de8d` VALUES (8.61, 101, 141101, -285, "ゲームの世界、ね\n分からないことばかりだけれど\nやることは変わらないわ\nどんな場所でもわたしは負けない！", 1022105, "2026/10/31 12:00:00", 10221, 3, 0, "2030/01/01 14:59:59", 1, 61, "アーモンドアイ");
INSERT INTO `v1_ec9a5cee5b2d79422c14537557cebe750643eeb1cd28a484957644dacc16de8d` VALUES (2.69, 202, 141201, -285, "（剣と魔法！　ええなぁ～！\nうちも魔法覚えられるやろか\nレースの後に花咲かせたり…\nくぅ～っ！　はよ試したいわ！）", 1022106, "2026/10/31 12:00:00", 10221, 2, 0, "2030/01/01 14:59:59", 1, 61, "ラッキーライラック");
INSERT INTO `v1_ec9a5cee5b2d79422c14537557cebe750643eeb1cd28a484957644dacc16de8d` VALUES (8.26, 301, 141301, -285, "なんて美しい世界でしょう…！\n現実では見られない景色ばかり\nぜひ一度、この世界の大自然を\n隅から隅まで駆け抜けてみたいです", 1022107, "2026/10/31 12:00:00", 10221, 1, 0, "2030/01/01 14:59:59", 2, 61, "デアリングタクト");
INSERT INTO `v1_ec9a5cee5b2d79422c14537557cebe750643eeb1cd28a484957644dacc16de8d` VALUES (8.79, 401, 141001, -285, "来ったぞ～来ったぞ～\nアストルム～っと！\nな～んか平和そうな世界だな\nちょっくら盛り上げてくっか！", 1022108, "2026/10/31 12:00:00", 10221, 1, 0, "2030/01/01 14:59:59", 2, 61, "ゴールドシップ");
INSERT INTO `v1_ec9a5cee5b2d79422c14537557cebe750643eeb1cd28a484957644dacc16de8d` VALUES (3.414, 1, 190801, -416.5, "ミッションをクリアすると、\n報酬がもらえますよ！\n頑張ってください", 2000001, "2026/04/10 12:00:00", 2, 2, 0, "2030/01/01 14:59:59", 1, 62, "カリン");
INSERT INTO `v1_ec9a5cee5b2d79422c14537557cebe750643eeb1cd28a484957644dacc16de8d` VALUES (3.099, 2, 190801, -416.5, "ミッションをクリアして、\n報酬をゲットしましょう！", 2000002, "2026/04/10 12:00:00", 2, 2, 0, "2030/01/01 14:59:59", 1, 62, "カリン");
INSERT INTO `v1_ec9a5cee5b2d79422c14537557cebe750643eeb1cd28a484957644dacc16de8d` VALUES (2.801, 3, 190801, -416.5, "受け取ることができる\n報酬があるようです\n確認してみてください", 2000003, "2026/04/10 12:00:00", 2, 2, 0, "2030/01/01 14:59:59", 1, 63, "カリン");
INSERT INTO `v1_ec9a5cee5b2d79422c14537557cebe750643eeb1cd28a484957644dacc16de8d` VALUES (0, 4, 190801, -416.5, "報酬がもらえますよ！\nチェックしてみてください", 2000004, "2026/04/10 12:00:00", 2, 2, 0, "2030/01/01 14:59:59", 2, 63, "カリン");
INSERT INTO `v1_ec9a5cee5b2d79422c14537557cebe750643eeb1cd28a484957644dacc16de8d` VALUES (2.12, 5, 190801, -363, "ギルド管理協会です！\nイベント報酬券をお持ちでしたら、様々なアイテムと交換できますよ", 2000005, "2026/04/10 12:00:00", 2, 1, 0, "2030/01/01 14:59:59", 2, 64, "カリン");
INSERT INTO `v1_ec9a5cee5b2d79422c14537557cebe750643eeb1cd28a484957644dacc16de8d` VALUES (1.68, 6, 190801, -363, "お疲れさまです！\nこちらでイベント報酬券とアイテムを交換することができますよ", 2000006, "2026/04/10 12:00:00", 2, 2, 0, "2030/01/01 14:59:59", 1, 64, "カリン");
INSERT INTO `v1_ec9a5cee5b2d79422c14537557cebe750643eeb1cd28a484957644dacc16de8d` VALUES (2.33, 7, 190801, -363, "いつもありがとうございます！\n報酬交換ですか？\nでは、イベント報酬券とお引き換えいたしますね", 2000007, "2026/04/10 12:00:00", 2, 1, 0, "2030/01/01 14:59:59", 2, 64, "カリン");
